-- State transitions declared for StockReconciliation: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION inventory.stock_reconciliations_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('draft', 'submitted'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: stock_reconciliations.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_stock_reconciliations__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS stock_reconciliations_status_transition_check ON inventory.stock_reconciliations;
CREATE TRIGGER stock_reconciliations_status_transition_check
    BEFORE UPDATE OF "status" ON inventory.stock_reconciliations
    FOR EACH ROW EXECUTE FUNCTION inventory.stock_reconciliations_status_transition_check();
